//Approach 1: Using 3 arrays to memoizise the previous states. TC: O(n) SC: O(n)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n=prices.size();
        if(n<=1)
            return 0;
        vector<int> selling(n,0),buying(n,0),cooldown(n,0);
        cooldown[0]=0;
        selling[0]=INT_MIN;
        buying[0]=-prices[0];
        for(int i=1;i<n;i++)
        {
            cooldown[i]=max(cooldown[i-1],selling[i-1]);
            buying[i]=max(buying[i-1],cooldown[i-1]-prices[i]);
            selling[i]=buying[i-1]+prices[i];
        }
        return max(cooldown[n-1],selling[n-1]);
    }
};
//Approach 2: Using state optimisation. TC: O(n) SC: O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n=prices.size();
        int selling=0,cooldown=0,buying=-prices[0];
        for(int i=0;i<n;i++)
        {
            int prevselling=selling;
            selling=buying+prices[i];
            buying=max(buying,cooldown-prices[i]);
            cooldown=max(cooldown,prevselling);
        }
        return max(cooldown,selling);
    }
};

class Solution(object):
    def maxProfit(self, prices):
        """
        :type prices: List[int]
        :rtype: int
        """
        self.prices = prices
        return self.recurse(0, 1, 0)

    def recurse(self, idx, state, price):
        if idx >= len(self.prices): 
            return 0
        # 2 kinds of state: [bought - 0, sold - 1]
        if state==0:
            if self.prices[idx]>price:
                p1 = (self.prices[idx]-price)+self.recurse(idx+2, 1, 0)
                p2 = self.recurse(idx+1, 0, price)
                return max(p1, p2)
            else:
                return self.recurse(idx+1, 0, price)
        else:
            p1 = self.recurse(idx, 0, self.prices[idx])
            p2 = self.recurse(idx+1, 1, 0)
            return max(p1, p2)

# Dynamic programming
class Solution(object):
    def maxProfit(self, prices):
        """
        :type prices: List[int]
        :rtype: int
        """
        if len(prices) < 2:
            return 0
        dp1 = [0] * len(prices)  # hold the stack on day i
        dp2 = [0] * len(prices)  # do not hold the stack on day i
        for i in range(1, len(prices)):
            dp1[i] = max(dp1[i - 1] + prices[i] - prices[i - 1], dp2[i - 1])
            dp2[i] = max(dp1[i - 1], dp2[i - 1])
        return max(dp1[-1], dp2[-1])
